ROOT = Path(__file__).resolve().parents[1]
ASSETS = ROOT / 'app/src/main/assets'
DATA = {}
MCQ = {}

def Q(ch, number, question, answer, mcq=False):
    key=f'g7_ch{ch:02}_{"mcq" if mcq else "q"}{number:02}'
    DATA[key]=dict(question=[T(question)] if isinstance(question,str) else question,
                   answer=[T(answer)] if isinstance(answer,str) else answer)

def first(ch, answer):
    template=re.sub(r'^۱-\s*','',CLOZE[ch][0]).replace('حرگت','حرکت')
    Q(ch,1,[C(template)],answer)

