Q(6,2,'چرا مطالعه آب ها در کشور ما از اهمیت زیادی برخوردار است ؟','زیرا کشور ما به طور طبیعی روی نوار بیابانی دنیا واقع شده و کم آبی یک مشکل اساسی در آن است .')
Q(6,3,[T('با توجه به نمودار ، به سؤالات پاسخ دهید :'),F('pdf:workbook.pdf#20,36,424,248,580'),C('الف- میانگین بارش در کدام استان از بقیه کمتر است ؟ {{0}}\nب- چرا مقدار بارندگی در شهر های کشورمان با هم فرق دارد ؟ ( دو دلیل بیاورید ) {{1}}')],'الف- اصفهان\nب- دوری و نزدیکی به دریا ها ، جهت وزش بادها ، میزان ناهمواری ها و موقعیت جغرافیایی شهر ها با هم فرق دارد .')
Q(6,4,'تفسیر کنید :\n« آب ، فراوان اما کمیاب »','بیشتر آب های کره زمین ( حدود ۹۷ درصد ) در دریا ها و اقیانوس ها قرار دارند ، که شور می باشند و فقط درصد کمی ( حدود ۳ درصد ) از آب ها شیرین هستند .')
Q(6,5,'با استفاده از مواد و وسایل زیر ، آزمایشی طرح کنید که تشکیل ابر و باران را نشان دهد .\n(( بشر یا لیوان ۲ عدد – نایلون – کش – یخ ))','در یک لیوان شیشه ای کمی آب گرم می ریزیم و درب آن را یک نایلون ( با کمک کش ) طوری می بندیم که نایلون کمی گود باشد . یک لیوان دیگر را بدون آب همین کار را می کنیم . سپس مقداری یخ را روی هر دو نایلون می ریزیم و صبر می کنیم . می بینیم که در لیوان آب گرم ، بخارات آب به نایلون برخورد کرده و سرد می شوند و قطرات آب شروع به ریختن می کنند ( مانند باران ) .\nدر لیوان دومی بخار هوای لیوان به مقدار خیلی کم پس از سرد شدن نمایان می شوند ( ابر ) و مقدار خیلی کمی هم از قطرات ریز به هم می پیوندند و می افتند ( باران )')
Q(6,6,[T('نمودار دایره ای توزیع آب در آب کره زمین به صورت زیر است ؛ متن زیر تفسیر این نمودار است .\nشما با استفاده از کلمات داده شده آن را کامل کنید :'),F('pdf:workbook.pdf#21,42.6,57.3,282.31,217.35'),C('(( آب های زیر زمینی – شور – یخچال ها – دریاچه ها – شیرین ))\n« حدود ۹۷ درصد حجم آب کره ، در دریا ها و اقیانوسها قرار دارد که {{0}} هستند و فقط حدود ۳ درصد آنها {{1}} می باشد .\nاین ۳ درصد شامل : {{2}} و {{3}} و {{4}} می باشند .\nکه {{5}} بزرگ ترین ذخیره آب شیرین زمین می باشند . »')],'به ترتیب : شور – شیرین – یخچال ها – آب های زیر زمینی – دریاچه ها – یخچال ها')
Q(6,7,[C('هر کدام چگونه تشکیل می شود ؟\nالف- برف : {{0}}\nب- باران : {{1}}\nج- تگرگ : {{2}}')],'الف- برف : اگر هنگام متراکم شدن ابرها ، دمای هوا خیلی کم باشد ، رطوبت هوا به شکل برف به زمین می ریزد .\nب- باران : در صورتی دمای هوا هنگام تراکم ابر ها ، بالاتر از صفر درجه سلسیوس باشد ، رطوبت هوا به شکل باران به زمین می ریزد .\nج- تگرگ : اگر قطره های باران در مسیر پایین آمدن به سطح زمین ، از توده هوای سرد عبور کند ، به تگرگ تبدیل می شوند .')
Q(6,8,[C('تعریف کنید :\nالف- آب کره : {{0}}\nب- هواشناسی : {{1}}\nج- حوضه آبریز : {{2}}')],'الف- آب کره : به مجموعه آب های موجود در هوا کره ( اتمسفر ) ، سطح و درون زمین که به صورت جامد ، مایع و بخار می باشند ، آب کره گفته می شود .\nب- هوا شناسی دانشی است که در باره شناخت جو و هوای اطراف کره زمین به مطالعه و تحقیق می پردازد .\nج- حوضه آبریز : منطقه ای که آب های سطحی آن توسط یک رود و انشعابات آن از نقاط مرتفع به سمت نواحی پست تر هدایت می شود .')
Q(6,9,'با استفاده از یک ظرف شیشه ای ، یک لیوان آب و مقداری ماسه و رس ، آزمایشی طرح کنید که نشان دهد باران هنگام بارش به کجا می رود .','در یک ظرف شیشه ای مخلوطی از ماسه و رس را می ریزیم و به صورت شیبدار در می آوریم و یک لیوان آب را از بالای شیب می ریزیم . مشاهده می کنیم که مقداری از آب ها فرو می رود و مقداری هم روی سطح خاک جاری می شود .')
Q(6,10,[T('پس از بارش ، چه اتفاقی برای آب ها می افتد ؟'),F('pdf:workbook.pdf#21,38.2,699.9,282.45,811.65')],'بخشی از آب تبخیر شده و به اتمسفر صعود می کند .\nبخشی از آب در سطح زمین جاری می شود .\nبخشی از آب هم به درون زمین نفوذ می کند .')
Q(6,11,[T('الف- آبشار ( تند آب ) چگونه به وجود می آید ؟'),I(),T('ب- در کدام حالت زیر ، امکان تشکیل آبشار وجود دارد ؟ توضیح دهید .'),F('pdf:workbook.pdf#22,45,122,400,233')],'الف- رود خانه در ادامه مسیر خود ممکن است به محلی برسد که بستر آن به طور ناگهانی دچار اختلاف ارتفاع شود . در این صورت آبشار ( تند آب ) ایجاد می گردد .\nب- شکل الف ، زیرا علت تشکیل آبشار این است که آب در مسیر خود ابتدا از سنگ های سخت و مقاوم سپس از سنگ های نرم و کم مقاومت عبور نماید .')
