Q(6,12,[T('آرش به همراه خانواده اش برای تفریح به کنار رودخانه ای رفتند . در پایان روز آرش ، زباله ها را در رود خانه رها نکرد ، بلکه آنها را در کیسه زباله ریخت تا در اولین فرصت آنها را به سطل آشغال منتقل کند .'),F('pdf:workbook.pdf#22,42.6,304.92,177.48,435.62'),C('الف- به نظر شما ، آیا آرش کار درستی انجام داده است ؟ {{0}}\nب- عوامل آلوده کننده آب رود خانه ها را بنویسید . {{1}}\nج- آلودگی رود خانه چه مشکلاتی را ایجاد می کند ؟ {{2}}')],'الف- بله\nب- ریختن زباله در آب ، ورود فاضلاب های خانگی و صنعتی در آب ، سموم کشاورزی\nج- از بین رفتن موجودات آبزی ، افزایش میکروب ها و بیماریها ، ناسالم شدن آب آشامیدنی و کشاورزی')
Q(6,13,[C('الف- دریاچه چیست ؟ {{0}}\nب- دریاچه ها چه اهمیتی دارند ؟ ( ۶ مورد ) {{1}}')],'الف- دریاچه : بخشی از آب کره که در سطح خشکی ها واقع شده است و به طور طبیعی به آب های آزاد راه ندارد .\nب- تأمین مواد غذایی ، مواد معدنی ، ذخایر نفت و گاز ، گردشگری ، تعدیل آب و هوای منطقه ، حمل و نقل و کشتیرانی')
Q(6,14,[C('هر کدام از موارد زیر مربوط به کدام دریاچه است ؟\n(( خزر – دریاچه غار علیصدر – ارومیه – سبلان ))\nالف- این دریاچه در استان اردبیل قرار دارد و در دهانه آتشفشان تشکیل شده است . ( {{0}} )\nب- بزرگ ترین دریاچه جهان است که باقیمانده دریای قدیمی به نام تتیس است . ( {{1}} )\nج- این دریاچه در استان همدان و به علت بالا تر بودن سطح آب زیر زمینی از کف غار تشکیل می شود . ( {{2}} )\nد- این دریاچه در استان آذر بایجان غربی و به علت شکستگی های قسمتی از سنگ کره تشکیل شده است . ( {{3}} )')],'الف- سبلان  ب- خزر  ج- دریاچه غار علیصدر  د- ارومیه')
Q(6,15,[C('اهداف تشکیل هر کدام از دریاچه های مصنوعی زیر را بنویسید . ( سه مورد برای هرکدام )\nالف- سد امیر کبیر در شمال شهر کرج : {{0}}\nب- دریاچه مصنوعی شهدای خلیج فارس در منطقه چیتگر تهران : {{1}}')],'الف- تولید برق ، کشاورزی ، آب آشامیدنی\nب- تعدیل دمای آب و هوا ، حفظ محیط زیست ، توسعه گردشگری')
Q(6,16,[T('در منطقه A جنس سنگ ها سخت و در منطقه B جنس سنگ ها نرم است . شکل سواحل این دو منطقه را با هم مقایسه کنید .'),F('pdf:workbook.pdf#23,70,203,265,307'),C('A : {{0}}\nB : {{1}}')],'منطقه A : صخره ای و پرتگاهی\nمنطقه B : هموار و ماسه ای')
Q(6,17,'دو مورد از عوامل آلوده کننده دریا ها و دریاچه ها را بنویسید .','فاضلاب کارخانه ها ، نشت نفت از نفت کش ها ، فاضلاب کشتی ها')
