Q(6,19,'آبتاز ( سونامی ) چیست ؟','هنگام وقوع زمین لرزه و آتشفشان های زیر دریایی ، امواج بزرگی در دریا ایجاد می شود که به آن آبتاز ( سونامی ) می گویند .')
Q(6,20,'الف- جزر و مد را تعریف کنید .\nب- جزر و مد چگونه ایجاد می شود ؟\nج- از جزر و مد چه استفاده هایی می کنند ؟ ( دو مورد )','الف- به بالا آمدن آب و حرکت آن به سمت ساحل مد و به پایین رفتن آب در سواحل ، جزر گفته می شود .\nب- در اثر نیروی گرانشی ماه و خورشید\nج- تولید انرژی الکتریسیته ، ماهیگیری')
Q(6,21,'الف- یخچال طبیعی چگونه تشکیل می شود ؟\nب- دو نوع یخچال طبیعی را نام ببرید و هر کدام در کجا تشکیل می شوند ؟','الف- با انباشته شدن برف در طی چندین سال ، در مناطقی از زمین که میانگین دمای هوا کمتر از صفر درجه سلسیوس است ، یخچال تشکیل می شود .\nب- ۱- قطبی : در نواحی قطب شمال و جنوب کره زمین\n۲- کوهستانی : در نواحی بالای کوه ها')

first(7,'به ترتیب : a- اندازه ذرات  b- نفوذ پذیری  c- آبرفت ها – رس ها\nd- سطح ایستابی  e- آزاد  f- آب سخت  g- قنات  h- آتشفشان ها')
Q(7,2,'رایج ترین راه های دستیابی به منابع آب های زیر زمینی کدامند ؟','حفر چاه و قنات')
Q(7,3,[C('زمین کشاورزی رضا ، بیش تر از شن و ماسه تشکیل شده است و گیاهانی که کاشته است ، محصولات خوبی نمی دهند .\nالف- به نظر شما ، او برای رفع این مشکل باید چکار کند ؟ {{0}}\nب- چرا زمین هایی که مقدار نفوذ پذیری خاک آن ها زیاد است ( شن و ماسه آن ها زیاد است ) ، برای کشاورزی مناسب نیستند ؟ {{1}}')],'الف- باید مقداری خاک رس به زمین اضافه کند .\nب- زیرا آب به سرعت در این خاک پایین می رود و از کنار ریشه گیاه سریع رد شده و به خوبی به گیاه آب نمی رسد .')
Q(7,4,[T('الف- مقدار نفوذ آب به درون زمین را در دو دامنه شکل زیر ، با هم مقایسه کنید .'),F('pdf:workbook.pdf#24,38.4,624.21,243.11,733.21'),C('{{0}}\nب- احداث سد در کدام دامنه بیشتر مورد نیاز است ؟ دلیل خود را بنویسید . {{1}}')],'الف- در دامنه ( الف ) آب بیش تری در زمین نفوذ می کند زیرا پوشش گیاهی جلوی آب را می گیرد ولی در دامنه ( ب ) آب به سرعت پایین می رود .\nب- در دامنه ( ب ) زیرا آب به سرعت پایین می رود و هدر می رود . برای جلوگیری از هدر رفتن آب ، سد احداث می کنند .')
Q(7,5,[T('آزمایشی طرح کنید که با انجام آن بتوانید میزان نفوذ پذیری آب را در ماسه ، رس و مخلوط ماسه و رس با هم مقایسه کنید .'),F('pdf:workbook.pdf#25,31.5,51,159,137.25'),C('{{0}}\nب- آیا از این آزمایش می توان نتیجه گرفت که میزان نفوذ پذیری آب به ترتیب زیر است ؟ {{1}}'),M('رس','<','مخلوط',FR('۲','۳'),'رس و',FR('۱','۳'),'ماسه','<','مخلوط',FR('۲','۳'),'ماسه و',FR('۱','۳'),'رس','<','ماسه'),C('ج- کدام خاک برای کشاورزی مناسب تر است ؟ چرا ؟ {{2}}')],[T('چهار گلدان کوچک که ته آنها سوراخ کوچکی است بر می داریم و شماره گذاری می کنیم . در شماره ۱ فقط ماسه می ریزیم . در شماره ۲ مخلوطی از دو لیوان ماسه و یک لیوان رس می ریزیم . در شماره ۳ مخلوطی از دو لیوان رس و یک لیوان ماسه می ریزیم و در شماره ۴ فقط رس می ریزیم .\nدر هر کدام مقدار مساوی آب می ریزیم . سرعت نفوذ آب در خاک و خروج آب از هر کدام را مشاهده می کنیم .\nب- بله\nج- مخلوط'),M(FR('۲','۳'),'رس و',FR('۱','۳'),'ماسه'),T('زیرا هم نفوذ پذیری و هم قدرت نگه داری آب مناسبی دارد .')])
Q(7,6,'میزان نفوذ پذیری آب در خاک به چه عواملی بستگی دارد ؟','پوشش گیاهی ، اندازه ذرات زمین ، شیب زمین')
Q(7,7,[T('متن زیر را به دقت بخوانید و به سؤالات مطرح شده پاسخ دهید .\n« اکثر گیاهان در خاکی بهتر رشد می کنند که میزان شن و ماسه و خاک رس و گیاخاک آن به مقدار مناسبی باشد . اگر مقدار شن و ماسه خیلی بیش از اندازه باشد ، آب به سرعت نفوذ می کند و از دسترس ریشه ها دور می شود و اگر مقدار رس خیلی بیش تر از اندازه باشد ، خاک سخت و محکم می شود و آب خیلی به سختی نفوذ می کند .\nستایش هنگام آب دادن به گل هایش ، در دو گلدان با دو مشکل متفاوت روبرو شد ؛ در گلدان شمعدانی ، متوجه شد که خاک گلدان خیلی سفت است و آب خیلی دیر در آن نفوذ می کند و لی در گلدان گل ارکیده آب به سرعت نفوذ می کند و از ته گلدان سریع خارج می شود . »'),C('۱- به نظر شما او برای رفع مشکل خاک گلدان شمعدانی باید چکار کند ؟ {{0}}\n۲- او برای رفع مشکل خاک گلدان ارکیده باید چکار کند ؟ {{1}}')],'۱- مقدار رس این گلدان خیلی زیاد است پس باید مقداری از خاک گلدان را بر دارد و به جای آن مقداری ماسه و گیاخاک به بقیه خاک مخلوط کند .\n۲- مقدار ماسه این گلدان خیلی زیاد است ؛ باید مقداری از خاک گلدان را بر دارد و مقداری رس به بقیه خاک مخلوط کند .')
Q(7,8,[C('متن زیر را با استفاده از کلمات داخل پرانتز کامل کنید :\n« در صورتی میزان نفوذ آب در زمین کمتر می شود که ؛ مقدار پوشش گیاهی {{0}} ( بیشتر – کمتر ) و اندازه ذرات {{1}} ( بزرگ تر – کوچک تر ) و شیب زمین {{2}} ( بیشتر – کمتر ) باشد . »')],'به ترتیب : کمتر – کوچک تر – بیشتر')
Q(7,9,'ذخایر آب های زیر زمینی چگونه به وجود می آیند ؟','آب های سطحی پس از نفوذ در درون زمین ، فضاهای خالی بین ذره های رسوبات و سنگ ها را پر می کنند و ذخایر آب های زیر زمینی را به وجود می آورند .')
Q(7,10,'غار های آهکی چگونه تشکیل می شوند ؟','آب های زیر زمینی هنگام نفوذ در سنگ های آهکی ، آن ها را در خود حل و فضاهای خالی ایجاد می کنند . با ادامه این فرایند فضاهای خالی بیشتر و بزرگ تر می شود و غار های آهکی به وجود می آید .')
Q(7,11,'آزمایشی طراحی کنید که با انجام آن بتوانید میزان فضاهای خالی بین ذرات ماسه را اندازه بگیرید .','یک بشر یا لیوان را از ماسه پر می کنیم . با استوانه مدرج به آن ، آب اضافه می کنیم تا از آب کاملا پر شود . حجم آبی را که استفاده کردیم و یادداشت کردیم ، در واقع همان حجم فضای خالی بین ماسه ها می باشد .')
Q(7,12,'برای بهره برداری از آب های زیر زمینی ، حفر چاه در زمین های آبرفتی مناسب تر است یا زمین های رسی ؟ دلیل خود را بنویسید .','آبرفتی زیرا فضاهای خالی بین ذرات آبرفتی زیاد است و آب های زیادی را در خود جای داده اند .')
Q(7,13,[T('با توجه به شکل های زیر ( وضعیت ذرات خاک ) ، به سؤالات پاسخ دهید :'),F('pdf:workbook.pdf#26,40,444,221,560'),C('الف- میزان فضاهای خالی و نفوذ پذیری در کدام یک بیشتر است ؟ چرا ؟ {{0}}\nب- کدام یک برای تشکیل ذخیره آب زیر زمینی مناسب تر است ؟ چرا ؟ {{1}}')],'الف- شکل ۲ زیرا بیشتر ذرات آن دانه درشت است .\nب- شکل ۲ زیرا فضاهای خالی بین ذرات آن بیشتر است .')
Q(7,14,[T('الف- شکل زیر یک آبخوان ( سفره آب زیر زمینی ) را نشان می دهد . هر کدام از شماره های ۱ و ۲ و ۳ محل کدام یک از موارد زیر می باشد :\n( سطح ایستابی – منطقه اشباع – عمق سطح ایستابی )'),F('pdf:workbook.pdf#26,45,629.24,242.48,800.19'),C('۱- {{0}}\n۲- {{1}}\n۳- {{2}}\nب- آیا منطقه اشباع ، سفره آب زیر زمینی می باشد ؟ ...............')],'۱- عمق سطح ایستابی ( منطقه بالایی )\n۲- سطح ایستابی\n۳- منطقه اشباع')
Q(7,15,'چگونه می توانید به وسیله یک ظرف شیشه ای و مقداری ماسه و مقداری آب ، یک آبخوان ( سفره آب زیر زمینی ) را شبیه سازی کنید ؟','بیشتر یک ظرف شیشه ای را ماسه می ریزیم و سپس تا نیمه آن را آب می ریزیم . دو منطقه به وجود می آید که در منطقه بالایی ماسه ها مرطوب اند ولی در منطقه پایینی فضای بین ماسه ها را آب پر کرده است که منطقه اشباع نام دارد . این منطقه همانند سفره آب زیر زمینی است .')
Q(7,16,[C('الف- عمق سطح ایستابی را در استان گیلان و یزد با هم مقایسه کنید . {{0}}\nب- عمق چاه های آب در استان های {{1}} ( خشک مرکزی – ساحلی ) کم است و با چند متر حفر کردن چاه به سطح ایستابی می رسیم ولی در استان های {{2}} ( خشک مرکزی – ساحلی ) این عمق زیاد است و امکان دارد بیش از ۱۵۰ متر باشد .')],'الف- عمق سطح ایستابی در استان یزد بیش تر از گیلان است ، زیرا در یزد بارندگی کم ولی در گیلان زیاد است و گیلان به دریا نزدیک است .\nب- به ترتیب : ساحلی – خشک مرکزی')
Q(7,17,'عمق سطح ایستابی به چه عواملی بستگی دارد ؟','میزان بارندگی ، نوع آب و هوا ، میزان بهره برداری از آب های زیر زمینی ، دوری و نزدیکی به ساحل ، میزان نفوذ پذیری خاک')
Q(7,18,'دو نوع سفره آب زیر زمینی ( آبخوان ) را نام ببرید .\n۱- ........................  ۲- ........................','۱- آزاد  ۲- تحت فشار')
Q(7,19,[T('با توجه به شکل مقابل ، به سؤالات زیر پاسخ دهید :'),F('pdf:workbook.pdf#27,38.4,366.38,303.84,480.98'),C('الف- این شکل ، کدام نوع سفره آب زیر زمینی ( آبخوان ) را نشان می دهد ؟ {{0}}\nب- در این نوع سفره ها ، یک لایه {{1}} روی یک لایه {{2}} قرار دارد .\nج- این نوع آبخوان ها بیشتر در .................... و .................... ایجاد می شود {{3}} و از آب موجود در این آبخوان ها با حفر .................... و .................... بهره برداری می کنند . {{4}}')],'الف- آزاد\nب- نفوذ پذیر – نفوذ ناپذیر\nج- به ترتیب : دشت ها و دامنه کوه ها – چاه و قنات')
Q(7,20,[T('با توجه به شکل مقابل ، به سؤالات زیر پاسخ دهید :'),F('pdf:workbook.pdf#27,30.05,585.41,331.29,725.91|-27,280,582,332,591'),C('الف- این شکل ، کدام نوع سفره آب زیر زمینی ( آبخوان ) را نشان می دهد ؟ {{0}}\nب- این نوع سفره آب زیر زمینی در جایی تشکیل می شود که یک لایه {{1}} بین دو لایه {{2}} قرار گیرد .\nج- این نوع آبخوان ، بیشتر در نواحی .................... و .................... ایجاد می شود . {{3}}')],'الف- تحت فشار\nب- نفوذ پذیر – نفوذ ناپذیر\nج- کوهستانی و شیب دار')
Q(7,21,'میلاد همراه خانواده اش برای تفریح به کنار یک چشمه رفته بود و چگونگی تشکیل چشمه را برای خانواده اش توضیح داد .\nشما هم بنویسید که چشمه چگونه تشکیل می شود ؟','در صورتی که در مناطق شیب دار ، آب های زیر زمینی به طور طبیعی به سطح زمین برسند و جاری شوند ، چشمه به وجود می آید .')
Q(7,22,'پیش بینی کنید ؛ اگر امسال زمستان برف کم تری ببارد ، آیا تابستان سال آینده ، آب چشمه ها بیش تر خواهد بود یا کم تر ؟ دلیل خود را بنویسید .','کم تر زیرا وقتی برف کم تری ببارد آب کم تری هم در زمین نفوذ کرده و آب های زیر زمینی کم تر می شوند ، در نتیجه آب چشمه کم تر می شود .')
Q(7,23,[T('برداشت بی رویه از آب های زیر زمینی باعث بروز چه مشکلاتی می گردد ؟'),F('pdf:workbook.pdf#28,39.75,265.51,269.2,380.26')],'سطح ایستابی پایین می رود و چاه ها خشک شده و در نتیجه بهره برداری از آن ها دشوارتر و گاهی نیاز به حفاری مجدد دارد تا به آب برسند . همچنین باعث نشست کردن زمین و آسیب رساندن به ساختمان ها می گردد .')
Q(7,24,'ویژگی های آب های زیر زمینی را بنویسید .','غالبا بی رنگ ، بی بو و فاقد مواد تیره کننده اند – ترکیب شیمیایی و دمای آن ها ثابت است – میزان آلودگی میکروبی آنها از آب های سطحی کمتر است ولی املاح معدنی محلول در آنها بیشتر است .')
Q(7,25,[T('آب های زیر زمینی چگونه آلوده می شوند ؟'),F('pdf:workbook.pdf#28,39.75,468.74,222,555.74')],'بر اثر نفوذ آب فاضلاب ها به آب های زیر زمینی .')
Q(7,26,[T('یاسین کلاس هفتم است . او با استفاده از روشی که در کتاب علوم خود یاد گرفته بود ، سماورشان را رسوب زدایی کرد .\nبه نظر شما او از چه روشی استفاده کرده است ؟'),F('pdf:workbook.pdf#28,61.5,588.36,129.15,679.88')],'منشأ این رسوبات ذرات آهک حاصل از مواد محلول در آب است ، مقداری سرکه را در سماور یا کتری ریخته ، مدتی صبر می کنیم تا سرکه رسوبات آهکی سماور یا کتری را در خود حل کند .')
Q(7,27,[C('تعریف کنید :\nالف- منطقه اشباع : {{0}}\nب- سطح ایستابی : {{1}}\nج- آب سخت : {{2}}')],'الف- منطقه ای که فضاهای خالی بین ذره های خاک در آن کاملا توسط آب پر شده است .\nب- به سطح بالایی منطقه اشباع ، سطح ایستابی گفته می شود .\nج- در صورتی که میزان کلسیم و منیزیم در آب زیاد باشد ، به آن آب سخت می گویند .')
Q(7,28,[T('شکل زیر ، چرخه آب را نشان می دهد .'),F('pdf:workbook.pdf#29,39.8,55.95,265.55,196.38'),C('الف- چرخه آب چیست ؟ {{0}}\nب- انرژی مورد نیاز چرخه آب از کجا تأمین می شود ؟ {{1}}')],'الف- آب پیوسته بین اقیانوس ها ، دریاها ، هواکره و خشکی ها مبادله می شود . به این گردش آب در طبیعت ، چرخه آب می گویند .\nب- خورشید')
MCQ[7]=[
 ('بزرگ ترین ذخیره آب شیرین در زمین ، کدام است ؟',['یخچال ها','آب های زیر زمینی','آب های جاری','دریاچه ها'],'الف'),
 ('مهم ترین املاح موجود در آب های زیر زمینی کدامند ؟',['آهن و منیزیم','کلسیم و منیزیم','کلسیم و فسفر','آهن و گوگرد'],'ب'),
 ('در کدام یک از استان های زیر عمق سطح ایستابی ( عمق چاه برای رسیدن به آب ) کم تر از بقیه است ؟',['اصفهان','کرمان','یزد','مازندران'],'د'),
 ('سرعت حرکت آب های زیر زمینی تقریبا در هر سال چقدر است ؟',['از ۱ متر تا ۱۰۰ متر','از ۰/۵ متر تا ۵۰۰ متر','از ۱/۵ متر تا ۵۰۰ متر','از ۰/۵ متر تا ۱۰۰۰ متر'],'ب'),
 ('ماهان برای اندازه گیری میزان فضاهای خالی بین ذرات ماسه ؛ ابتدا یک بشر را پر از ماسه کرد . سپس به وسیله استوانه مدرج مقدار ۵۰ سی سی آب روی آن ها ریخت ، هنوز بشر از آب پر نشده بود . سپس ۲۰ سی سی دیگر آب ریخت و کم کم به بشر اضافه کرد تا اینکه بشر از آب پر شد و ۸ سی سی آب در داخل استوانه مدرج اضافه آمد .\nحجم فضاهای خالی بین ماسه ها چند سانتی متر مکعب بوده است ؟',['۵۰','۷۰','۶۲','۶۸'],'ج'),
 ('شکل مقابل ، چه چیزی را نشان می دهد ؟',['چشمه','قنات ( کاریز )','چاه','آبخوان تحت فشار'],'ب')]

first(8,'به ترتیب : A- انرژی  B- کار  C- عمود  D- شیمیایی – حرکتی\nE- الکتریکی – صوتی  F- شیمیایی به گرمایی و نورانی\nG- الکتریکی به نورانی ، صوتی و گرمایی  H- جنبشی  I- کیلو کالری')
Q(8,2,[T('آزمایشی طرح کنید که نشان دهد مقدار کار به نیرو و جا به جایی بستگی دارد .'),F('pdf:workbook.pdf#30,34.95,396.98,189.4,546.5')],'در مرحله اول ؛ به وسیله نیروسنج ابتدا یک تخته چوبی را یک بار به اندازه ۳۰ سانتی متر و یک بار ۵۰ سانتی متر در یک جهت می کشیم و حاصل ضرب نیرویی که نیروسنج نشان می دهد در مقدار جا به جایی را یادداشت می کنیم . ( حاصل ضرب نیرو و جا به جایی همان مقدار کار می باشد ) .\nدر مرحله دوم همان اقدام را با دو تخته چوبی انجام می دهیم و مقدار کار را یادداشت می کنیم .\nمی بینیم که مقدار کار هم به مقدار نیرو و هم به مقدار جا به جایی بستگی دارد .')
Q(8,3,[T('وارد کردن نیرو به یک جسم ممکن است سبب چه تغییراتی در جسم شود ؟ ( زیر هر شکل بنویسید . )'),F('pdf:workbook.pdf#30,34.95,617.92,474.53,791.92')],'ردیف اول از راست به چپ : شروع حرکت – سریع تر شدن حرکت – کند شدن حرکت\nردیف دوم از راست به چپ : توقف حرکت – تغییر شکل جسم – تغییر جهت حرکت')
Q(8,4,[T('در کدام مورد نیروی دست از نظر علمی کار انجام نداده است ؟ دلیل انتخاب خود را بنویسید .'),F('pdf:workbook.pdf#31,27,55,468.3,174|-31,27,48,468.3,56'),C('حالت {{0}} زیرا : {{1}}')],'حالت ۳ زیرا نیرو بر جهت جا به جایی عمود می باشد .')
Q(8,5,'امید با نیروی افقی ۴۲۰ نیوتونی جعبه ای را به اندازه ۴ متر در امتداد نیروی وارد شده به آن ، جا به جا می کند .\nکاری که امید روی جعبه انجام می دهد ، چقدر است ؟',[M('کار = نیرو × جا به جایی = 420 × 4 = 1680'),T('ژول')])
Q(8,6,'رضا با وارد کردن نیروی ۵۰ نیوتونی جسمی را از زمین بلند کرد و آن را روی کمدی که ارتفاع آن ۱/۳ متر بود ، قرار داد .\nکار انجام شده توسط رضا را حساب کنید .',[M('کار = نیرو × جا به جایی = 50 × 1/3 = 65'),T('ژول')])
Q(8,7,[T('شادمهر با نیروی ۸۰ نیوتن یک جسم را بر روی سطح شیب دار که طولش ۳ متر بود ، هل داد و آن را به عقب کامیون منتقل کرد .\nولی دفعه بعد ، مسعود با نیروی ۲۴۰ نیوتون همان جسم را از زمین بلند کرد و به عقب کامیون که ارتفاعش از زمین ۱ متر بود ، منتقل کرد .\nالف- مقدار کاری را که هر فرد روی جسم انجام داده است را محاسبه و با هم مقایسه کنید .'),F('pdf:workbook.pdf#31,35.65,416,177.55,590.05'),T('ب- کدام روش برای جا به جایی جسم راحت تر است ؟ چرا ؟')],[M('کار = نیرو × جا به جایی = 80 × 3 = 240'),T('ژول'),M('کار = نیرو × جا به جایی = 240 × 1 = 240'),T('ژول\nمقدار کار هر دو یکسان است ( ۲۴۰ ژول )\nب- سطح شیب دار زیرا با اینکه مقدار کار در دو حالت یکسان است ولی در سطح شیبدار جسم با نیروی کمتری بالا می رود پس سطح شیبدار کار ما را آسانتر می کند .')])
Q(8,8,[T('متن زیر مربوط به تبدیلات انرژی در یک چراغ قوه است . با استفاده از کلمات داخل پرانتز ، جاهای خالی را تکمیل کنید .\nممکن است از یک کلمه بیش از یک بار استفاده گردد . ( نورانی – الکتریکی – شیمیایی – گرمایی )'),F('pdf:workbook.pdf#31,28.5,716.53,105.75,775.03'),C('« در یک چراغ قوه ، انرژی {{0}} ذخیره شده در باتری به انرژی {{1}} تبدیل می شود .\nپس از آن لامپ ، انرژی {{2}} را به انرژی {{3}} و انرژی {{4}} تبدیل می کند . »')],'به ترتیب : شیمیایی – الکتریکی – الکتریکی – نورانی – گرمایی')
Q(8,9,'انرژی جنبشی به چه عواملی بستگی دارد ؟','جرم جسم و سرعت جسم')
Q(8,10,[C('در هر کدام از موارد زیر ، انرژی جنبشی کدام شخص بیش تر است ؟ چرا ؟\nالف- جرم فرشاد ۳۲ کیلو گرم و جرم احسان ۲۸ کیلو گرم است ، ولی هر دو با سرعت یکسانی در حال دویدن هستند . {{0}}\nب- جرم فاطمه و رها مساوی یکدیگر ( ۴۱ کیلو گرم ) است ، ولی رها در مسابقه دو میدانی از فاطمه جلو زده است . {{1}}')],'الف- فرشاد . سرعت هر دو یکسان است ولی چون فرشاد جرم بیش تری دارد پس انرژی جنبشی بیشتری دارد .\nب- رها . جرم هر دو یکسان است ولی چون رها سرعت بیش تری دارد ، پس انرژی جنبشی بیش تری دارد .')
Q(8,11,'انرژی پتانسیل گرانشی به چه عواملی بستگی دارد ؟','وزن جسم و ارتفاع جسم از سطح زمین')
Q(8,12,[T('نقشه مفهومی زیر ، مربوط به سه نوع انرژی پتانسیل و مثال آن ها است . جاهای خالی را تکمیل کنید .'),B(['انواع انرژی پتانسیل','مانند'],[['۱- {{0:0}}','اجسام بالاتر از سطح زمین – آب پشت سد'],['۲- پتانسیل شیمیایی','{{0:1}}'],['۳- {{0:2}}','{{0:3}}']])],'۱- پتانسیل گرانشی\n۲- انرژی ذخیره شده در مواد غذایی و سوخت ها\n۳- پتانسیل کشسانی – انرژی فنر یا لاستیک کشیده شده')
Q(8,13,'آزمایشی طرح کنید که نشان دهد انرژی پتانسیل گرانشی به وزن جسم و ارتفاع جسم از سطح زمین بستگی دارد .','آزمایش صفحه ۶۸ کتاب و یا این آزمایش : مرحله اول ، از فاصله یک متری یک بار گلوله سبک و یک بار گلوله سنگین را رها می کنیم . می بینیم که گلوله سنگین ضربه بیش تری به زمین وارد و صدای ضربه آن بیش تر است . ( نقش وزن جسم )\nمرحله دوم : یک گلوله را یک بار از نیم متری زمین و بار دیگر همان گلوله را از یک متری زمین رها می کنیم . مشاهده می کنیم در حالتی که از یک متری رها شده ضربه بیش تری به زمین وارد و صدای ضربه آن بیش تر است ( نقش ارتفاع ) . و یا هر آزمایش مشابه دیگر')
Q(8,14,[T('وقتی از یک کمان کشیده شده تیری رها می گردد ، چه تبدیلات انرژی صورت می گیرد ؟'),F('pdf:workbook.pdf#32,34.95,678.64,263.5,782.08'),C('کمان کشیده شده دارای انرژی {{0}} است .\nبا رها کردن زه ( کش ) کمان ، انرژی {{1}} ذخیره شده ، به انرژی {{2}} پیکان تبدیل می شود .')],'به ترتیب : پتانسیل کشسانی – پتانسیل کشسانی – جنبشی ( حرکتی )')
Q(8,15,[T('متن زیر ، تفسیر شکل مقابل می باشد . با استفاده از کلمات ( جنبشی و پتانسیل گرانشی ) آن را کامل کنید :'),F('pdf:workbook.pdf#33,34.95,62.2,257.17,192.2'),C('« هر چه سنگ بالاتر برده شود ، انرژی {{0}} بیشتری در آن ذخیره می شود ، که هنگام رها کردن آن ، این انرژی به انرژی {{1}} بیشتری تبدیل می شود و در نتیجه سنگ ضربه بیشتری به جسم روی زمین وارد می کند . »')],'به ترتیب : پتانسیل گرانشی – جنبشی')
Q(8,16,'قانون پایستگی انرژی را بنویسید .','انرژی هرگز به وجود نمی آید یا از بین نمی رود . تنها شکل آن تغییر می کند و مقدار کل آن ثابت می ماند .')
Q(8,17,[T('با توجه به قانون پایستگی انرژی ، در شکل زیر جای خالی را روی نمودار انرژی یک خودرو ، کامل کنید .'),F('pdf:workbook.pdf#33,45,275,500,378')],'۱۱۰۰ ژول')
Q(8,18,[T('الف- نیما برای صبحانه ، یک عدد نان لواش ( حدود ۱۰۰ گرم ) و دو عدد تخم مرغ آب پز ( جمعا حدود ۱۲۰ گرم ) و یک لیوان شیر پر چرب ( حدود ۲۲۰ گرم ) صرف کرد . با توجه به جدول حساب کنید او با خوردن این صبحانه چقدر انرژی کسب کرده است ؟'),B(['خوراکی','انرژی ( کیلو ژول بر گرم )'],[['نان لواش','۱۱/۳'],['تخم مرغ ( آب پز )','۶/۸'],['شیر پر چرب','۳']]),T('ب- به نظر شما چرا خوردن صبحانه اهمیت زیادی دارد ؟')],[M('100 × 11/3 = 1130'),M('120 × 6/8 = 816'),M('220 × 3 = 660'),M('1130 + 816 + 660 = 2606'),T('کیلو ژول\nب- زیرا صبحانه می تواند انرژی و بسیاری از مواد لازم بدن را تأمین کند . بدون صبحانه انرژی لازم برای یاد گیری و فعالیت را نداریم .')])
Q(8,19,[T('شکل زیر را تفسیر کنید .'),F('pdf:workbook.pdf#33,35.65,676.69,334.1,784.98')],'انرژی ما برای انجام کارها ، از غذایی است که می خوریم . غذاهای ما ، مستقیم و غیر مستقیم از گیاهان است و گیاهان هم توسط نور خورشید غذا سازی می کنند ، پس منبع اصلی انرژی ما ، خورشید است .')
MCQ[8]=[
 ('در هر گرم از غذایی که می خوریم مقداری انرژی شیمیایی نهفته است که معمولا آن را با کدام یکا ( واحد ) بیان می کنند ؟',['ژول','کیلو ژول','ژول بر گرم','کیلو ژول بر گرم'],'د'),
 ('هر کیلو کالری معادل چند ژول است ؟',['۴۲۰۰','۱۰۰۰','۲۴۰۰','۴۲۰'],'الف'),
 ('اگر یک بستنی وانیلی حدود ۵۰ گرم باشد و انرژی هر گرم آن معادل ۹/۳ کیلو ژول باشد ، با خوردن یک بستنی وانیلی چند کیلو ژول بر گرم انرژی کسب می کنیم ؟',['۵۹۳','۵۹/۳','۴۶۵','۴۶۵۰'],'ج'),
 ('انرژی مورد نیاز یک نوجوان فعال و در حال رشد برای یک شبانه و روز به طور متوسط چند کیلو ژول است ؟',['۱۰۰۰۰ تا ۱۲۰۰۰','۴۰۰۰','۸۰۰۰ تا ۱۰۰۰۰','۱۵۰۰۰'],'الف'),
 ('در شکل زیر هر دو خودرو مشابه اند ، ولی خودروی شماره ۱ تندتر حرکت می کند . انرژی جنبشی آن ها را با هم مقایسه کنید .',['انرژی جنبشی هر دو یکسان است .','انرژی جنبشی هر دو صفر است .','انرژی جنبشی خودروی شماره ۱ بیشتر است زیرا سرعت بیشتری دارد .','انرژی جنبشی خودروی شماره ۲ بیشتر است زیرا سرعت کمتری دارد .'],'ج'),
 ('در شکل زیر ، خودرو و کامیون با یک سرعت حرکت می کنند . انرژی جنبشی ( حرکتی ) آن ها را با هم مقایسه کنید .',['انرژی جنبشی هر دو یکسان است .','انرژی جنبشی کامیون بیشتر است زیرا جرم بیشتری دارد .','انرژی جنبشی خودرو بیشتر است زیرا جرم کمتری دارد .','انرژی جنبشی هر دو صفر است .'],'ب'),
 ('گلوله ای را از نقطه A رها کرده ایم ، پس چند بار بالا و پایین رفتن ، سرانجام در نقطه D ایستاده است .\nدر کدام نقطه بیشترین انرژی پتانسیل گرانشی را داشته است ؟',['A','B','C','D'],'الف')]

first(9,'به ترتیب : A- خورشید  B- تجدید نا پذیر  C- سوخت هسته ای\nD- خطوط لوله  E- تجدید پذیر  F- زمین گرمایی')
Q(9,2,'تفاوت منابع انرژی تجدید پذیر با منابع انرژی تجدید نا پذیر از نظر پایداری چیست ؟','منابع انرژی تجدید پذیر تمام نشدنی ولی منابع انرژی تجدید نا پذیر ، تمام شدنی هستند .')
Q(9,3,[T('منابع انرژی زیر را به دو گروه تجدید پذیر و تجدید نا پذیر طبقه بندی کنید :\n(( باد – خورشید – گاز طبیعی – زغال سنگ – امواج دریا – جزر و مد – زمین گرمایی – نفت – سوخت های زیستی ( گیاهی ) – سوخت های هسته ای – برق آبی ))'),B(['منابع انرژی',''],[['۱- تجدید پذیر','{{0:0}}'],['۲- تجدید نا پذیر','{{0:1}}']])],'۱- تجدید پذیر : باد – خورشید – امواج دریا – جزر و مد – زمین گرمایی – سوخت های زیستی ( گیاهی ) – برق آبی\n۲- تجدید نا پذیر : گاز طبیعی – زغال سنگ – نفت – سوخت های هسته ای')
Q(9,4,[T('با توجه به شکل مقابل ، سوخت های فسیلی ( نفت ، گاز و زغال سنگ ) چگونه به وجود آمده اند ؟'),F('pdf:workbook.pdf#35,39.1,597.64,284.4,761.84'),C('الف- زغال سنگ : {{0}}\nب- نفت خام و گاز : {{1}}')],'الف- بقایای برخی از گیاهان میلیون ها سال پیش در لابلای گل و لای قرار گرفته و در اثر فشار زیاد و دمای مناسب به زغال سنگ تبدیل شدند .\nب- بقایای جانداران ذره بینی میلیون ها سال پیش در دریا در لابلای رسوبات قرار گرفته و بر اثر فشار زیاد و دمای مناسب به نفت و گاز تبدیل شدند .')
Q(9,5,[C('یک مزیت و یک عیب سوخت های فسیلی برای تولید انرژی را بنویسید .\nمزیت : {{0}}\nعیب : {{1}}')],'مزیت : به آسانی می سوزند و انرژی زیادی تولید می کنند .\nعیب : باعث آلودگی محیط زیست می شوند و تمام شدنی اند .')
Q(9,6,'برای صرفه جویی در مصرف انرژی الکتریکی در خانه تان ، دو راه پیشنهاد کنید .','خاموش کردن لامپ های اضافی – استفاده نکردن از وسایل برقی پرمصرف در هنگام شب ( در هنگام اوج مصرف ) – استفاده از لامپ های کم مصرف و ...')
Q(9,7,'چرا در کل جهان ، سرمایه گذاری و پژوهش درباره انرژی های تجدید پذیر ( خورشید ، باد و ... ) و استفاده از آن ها به سرعت در حال افزایش است ؟ ( سه دلیل بیاورید )','باعث آلودگی محیط زیست نمی شوند – باعث گرمایش جهانی نمی شوند – به طور مداوم جایگزین می شوند و تمام شدنی نیستند .')
Q(9,8,[T('الف- در صفحه های خورشیدی چه تبدیل انرژی صورت می گیرد ؟\nبیش تر صفحه های خورشیدی حدود یک پنجم یعنی ۲۰ درصد'),F('pdf:workbook.pdf#36,48.2,299.15,205.45,413.03'),C('انرژی {{0}} خورشید را به انرژی {{1}} تبدیل می کنند .\nب- چهار کاربرد صفحه های خورشیدی را بنویسید . {{2}}')],'الف- نورانی به الکتریکی\nب- ماشین حساب ، ماهواره ها ، چراغ ها و تابلوهای رانندگی ، بام و نمای ساختمان ها برای تولید انرژی الکتریکی خانه ، هواپیمای یک نفره')
Q(9,9,[T('طرز کار آبگرم کن های خورشیدی را بنویسید .'),F('pdf:workbook.pdf#36,34.95,483.96,189.34,604.16')],'در آب گرم کن های خورشیدی ، سطح لوله های تیره رنگ ، بر اثر برخورد نور خورشید گرم می شود . گرما به آبی که در لوله ها در گردش است داده می شود و سبب افزایش دمای آب تا حدود ۶۰ تا ۷۰ درجه سلسیوس می شود .')
Q(9,10,[T('الف- شکل روبرو استفاده از کدام منبع انرژی را نشان می دهد ؟'),F('pdf:workbook.pdf#36,34.95,626.57,175.3,777.52|-36,150,755,176,779'),C('{{0}}\nب- این منبع انرژی ، تجدید پذیر است یا تجدید نا پذیر ؟ {{1}}\nج- نام این دستگاه چیست ؟ {{2}}\nد- در این دستگاه چه تبدیل انرژی صورت می گیرد ؟ {{3}}')],'الف- باد\nب- تجدید پذیر\nج- توربین بادی\nد- انرژی جنبشی باد به انرژی الکتریکی تبدیل می شود .')
Q(9,11,[T('با توجه به شکل ، جمله زیر را تفسیر کنید :'),F('pdf:workbook.pdf#37,37,35.65,381.52,127.9'),T('« در توربین های بادی از انرژی خورشید به طور غیر مستقیم بهره برداری می شود . »')],'وقتی خورشید به زمین می تابد ، در اثر گرم شدن نابرابر سطح زمین ، باد به وجود می آید . باد همان هوای در حال حرکت است . یعنی در واقع انرژی باد ، از خورشید تأمین شده است .\nتوربین های بادی ، انرژی جنبشی باد را به انرژی الکتریکی تبدیل می کنند .')
Q(9,12,[T('متن زیر ، تفسیر شکل می باشد . جاهای خالی را تکمیل کنید .'),F('pdf:workbook.pdf#37,28.65,308.36,405.22,374.76'),C('« این شکل استفاده از انرژی {{0}} برای تولید انرژی الکتریکی را نشان می دهد . وزش باد در سطح دریا ، سبب ایجاد {{1}} می شود . هرچه انرژی {{2}} باد بیشتر باشد ، موج های بزرگ تر و پر انرژی تری به وجود می آید . برای مهار انرژی موج های دریا از توربین های ویژه ای استفاده می کنند . »')],'به ترتیب : موج های دریا – موج – جنبشی')
Q(9,13,[T('الف- شکل زیر ، استفاده از کدام منبع انرژی را نشان می دهد ؟'),F('pdf:workbook.pdf#37,37,557.11,291.25,723.41'),C('{{0}}\nب- این منبع انرژی ، تجدید پذیر است یا تجدید نا پذیر ؟ {{1}}\nج- این انرژی از کجا حاصل شده است ؟ {{2}}\nد- دو مورد از نشانه های وجود این انرژی در کره زمین را بنویسید . {{3}}\nه- چهار کاربرد این انرژی را بنویسید . {{4}}')],'الف- زمین گرمایی\nب- تجدید پذیر\nج- این انرژی حاصل از گرمای سنگ های داغ اعماق زمین است که در نواحی آتشفشانی وجود دارند .\nد- چشمه های آب گرم و آب های داغ در حال فوران ( آب فشان ) در برخی مناطق\nه- تولید انرژی الکتریکی ، گرمایش ساختمان ها ، فعالیت های صنعتی ، ایجاد مراکز گردشگری ، برای بهره مندی از خواص درمانی آب های گرم درون زمین')
Q(9,14,'اصطلاح سوخت های زیستی برای توصیف یک رشته محصولات که از طریق فتوسنتز به دست می آید ، به کار می رود .\nاین سوخت ها می توانند به شکل های جامد ، مایع و گاز مورد استفاده قرار گیرند :\nالف- قدیمی ترین شکل انرژی مورد استفاده بشر کدام است ؟\nب- شکل مایع سوخت های زیستی را چگونه به دست می آورند ؟ یک کاربرد آن را بنویسید .\nج- زیست گاز چیست ؟ دو کاربرد آن را بنویسید .','الف- شکل جامد آن یعنی چوب یا زغال\nب- از باقیمانده و تفاله های نیشکر به دست می آورند – در خودرو ها برای حمل و نقل\nج- هر گاه پسماند یا باقیمانده محصولات کشاورزی در شرایط بی هوازی ( نبود هوا ) قرار گیرند ، پس از مدتی گاز هایی از آن ها متصاعد می شود که به آن زیست گاز می گویند .\nبرای مصارف خانگی و صنعتی')
Q(9,15,[T('با توجه به شکل ، به سؤالات پاسخ دهید .'),F('pdf:workbook.pdf#38,34.25,269.79,286,517.24'),C('الف- شکل مقابل یکی از پاک ترین روش های تولید برق را نشان می دهد که به آن انرژی {{0}} می گویند .\nب- نام دستگاه های مشخص شده ( شماره ۱ و ۲ ) را بنویسید .\n۱- {{1}}\n۲- {{2}}\nج- انرژی پتانسیل گرانشی آب پشت سد توسط {{3}} و {{4}} به انرژی {{5}} تبدیل می شود .')],'الف- برق آبی\nب- ۱- توربین  ۲- مولد ( ژنراتور )\nج- به ترتیب : توربین ها – مولد ها – الکتریکی')
MCQ[9]=[
 ('کدام منبع انرژی تجدید پذیر از نظر ذخیره انرژی خورشیدی منحصر به فرد است ؟',['باد','سوخت های زیستی','امواج دریا','زمین گرمایی'],'ب'),
 ('در حال حاضر بیش از ۸۵ درصد از انرژی مورد نیاز بشر از چه طریقی تأمین می شود ؟',['آب','باد','سوخت های هسته ای','سوخت های فسیلی'],'د'),
 ('شکل مقابل استفاده از کدام منبع انرژی را نشان می دهد ؟',['زمین گرمایی','سوخت های فسیلی','سوخت های زیستی','سوخت های هسته ای'],'ج')]

first(10,'به ترتیب : A- دماسنج  B- گرما  C- ژول  D- رسانش\nE- همرفت  F- تابش')
Q(10,2,[T('طرز درجه بندی کردن دماسنج الکلی و جیوه ای را بنویسید .'),F('pdf:workbook.pdf#39,32.15,341.93,183.1,478.84')],'ابتدا مخزن آن ها را در مخلوط آب و یخ قرار می دهند و سطح جیوه یا الکل را با صفر نشانه گذاری می کنند سپس دماسنج را در مجاورت بخار آب در حال جوش قرار داده ، سطح مایع درون دماسنج را با عدد ۱۰۰ علامت گذاری می کنند . بین این دو عدد ( صفر تا ۱۰۰ ) را به صد قسمت مساوی تقسیم می کنند و هر قسمت را یک درجه سلسیوس می نامند .')
Q(10,3,[C('الف- چگونه با دماسنج های جیوه ای یا الکلی ، دمای یک جسم را اندازه می گیرید ؟ {{0}}\nب- دماسنج پزشکی چه کاربردی دارد ؟ {{1}}')],'الف- مخزن دماسنج را در تماس با جسم قرار می دهیم و مدتی صبر می کنیم . مایع دماسنج روبروی هر عددی ایستاد ، همان دمای جسم است .\nب- دمای بدن فرد بیمار را با دقت اندازه می گیرد .')
Q(10,4,[C('نگار برای نشان دادن مفهوم دمای تعادل گرما آزمایش زیر را انجام داد . شما جاهای خالی را با کلمات ( میخ و آب ) کامل کنید :\n« یک لیوان را تا نیمه آب سرد ریخت و به وسیله دماسنج دمای آب را اندازه گرفت ( ۱۴ درجه سانتی گراد بود ) . سپس یک میخ را به وسیله انبرک روی شعله گرفت تا داغ شود . میخ را داخل آب انداخت و کمی صبر کرد . دوباره دمای آب را اندازه گرفت . ( ۱۸ درجه شده بود ) .\nاو نتیجه گرفت که انرژی گرمایی از {{0}} به {{1}} منتقل شده است و پس از مدتی به دمای تعادل رسیده اند .\nیعنی در واقع {{2}} انرژی از دست داده و {{3}} انرژی گرفته است تا زمانی که به دمای تعادل برسند .\nولی وقتی که یک میخ بسیار سرد ( که داخل فریزر بوده ) را به داخل آب انداخت ، دمای آب کاهش یافت و پس از مدتی ثابت ماند .\nدر این حالت ؛ انرژی از {{4}} به {{5}} منتقل شده است . »')],'به ترتیب : میخ – آب – میخ – آب – آب – میخ')
Q(10,5,[T('دو جسم A و B با دمای متفاوت را به هم تماس داده ایم :'),B(['جسم','دما ( درجه سلسیوس )'],[['A','۲۸'],['B','۷۶']]),C('الف- جنبش ذرات کدام جسم بیش تر است ؟ چرا ؟ {{0}}\nب- گرما از کدام جسم به کدام جسم منتقل می شود ؟ چرا ؟ {{1}}\nج- انتقال انرژی گرمایی بین این دو جسم ، تا چه زمانی ادامه می یابد ؟ {{2}}\nد- پس از رسیدن به دمای تعادل ، جنبش ذره های دو جسم را با هم مقایسه کنید . {{3}}')],'الف- جسم B\nب- از جسم B به جسم A زیرا دمای جسم B بیشتر است . گرما از جسم گرم به جسم سرد منتقل می شود .\nج- تا هنگامی که دمای هر دو یکسان شود یعنی به دمای تعادل برسند ، در این حالت می گوییم دو جسم با یکدیگر در تعادل گرمایی اند .\nد- جنبش ذرات دو جسم یکسان می گردد .')
Q(10,6,[C('تعریف کنید :\nالف- گرما : {{0}}\nب- همرفت : {{1}}')],'الف- به مقدار انرژی که در اثر اختلاف دما از جسم گرم به جسم سرد منتقل می شود ، گرما گویند .\nب- در انتقال گرما به روش همرفت ، قسمتی از مایع یا گاز که گرم شده است ، به طرف بالا حرکت می کند و قسمت های اطراف آن که سردترند ، جای آن را می گیرند .')
Q(10,7,'سه راه انتقال گرما را نام ببرید .','رسانش ، همرفت ، تابش')
Q(10,8,'گرما چگونه از طریق رسانش ( رسانایی ) منتقل می گردد ؟','گرما جنبش اتم های جسم را بیش تر می کند و این اتم ها با برخورد به اتم های مجاور خود ، انرژی گرمایی را به آن ها منتقل می کنند و جنبش آن ها را هم بیش تر می کنند و این کار ادامه دارد تا اینکه گرما به طرف دیگر جسم منتقل شود .')
Q(10,9,[T('با استفاده از وسایل و مواد زیر ، آزمایشی طرح کنید که با انجام آن بتوانید میزان رسانایی گرمایی چند فلز را با هم مقایسه کنید .\n( میله آهنی و مسی و آلومینیمی – چوب کبریت – پارافین جامد یا شمع – چراغ گاز )'),F('pdf:workbook.pdf#40,33,546.63,192.75,689.13')],[T('به کمک پارافین ، به سر میله ها ، چوب کبریت را می چسبانیم و مطابق شکل سر دیگر میله ها را روی شعله قرار دادیم . پس از مدتی مشاهده کردیم ابتدا چوب کبریت متصل به میله مسی افتاد و کمی بعد مربوط به میله آلومینیمی افتاد و در آخر مربوط به میله آهنی افتاد .\nنتیجه گرفتیم میزان رسانایی گرمایی این سه فلز با هم فرق دارد و به این ترتیب است :'),M('آهن','<','آلومینیم','<','مس')])
Q(10,10,[C('الف- چرا وقتی با سیخ فلزی کباب درست می کنیم ، احتمال سوختن دستمان وجود دارد ؟ {{0}}\nب- در چه صورت دستمان نمی سوزد ؟ {{1}}')],'الف- زیرا سیخ فلزی رسانایی گرمایی خوبی دارد و گرما را سریع به سر دیگر منتقل می کند .\nب- باید با دستگیره عایق آن را بگیریم .')
Q(10,11,[C('به چه موادی رسانای گرما و به چه موادی نارسانا ( عایق ) گرما می گویند ؟ برای هر کدام مثال بزنید .\nرسانا : {{0}}\nنارسانا ( عایق ) : {{1}}')],'به موادی که گرما را بسیار سریع منتقل می کند ، رسانا می گویند مانند مس ، آلومینیم ، آهن و ...\nبه موادی که گرما را بسیار آهسته منتقل می کنند ، نارسانا ( عایق ) می گویند مانند شیشه ، چوب ، لاستیک ، هوا ، پشم')
Q(10,12,[C('الف- چرا پشم شیشه و فایبر گلاس ، نارسانای خوب محسوب می شوند ؟ {{0}}\nب- چه ویژگی در پنبه ، پشم و پر باعث شده که از آن ها در صنایع متفاوت از جمله صنایع نساجی ( تولید پارچه و پوشاک ) استفاده کنند ؟ {{1}}')],'الف- به علت داشتن هوای محبوس ( هوا نارسانا است )\nب- وجود هوا در لابلای پنبه و پشم و پر ، سبب کاهش میزان رسانایی گرمایی آن ها می شود .')
Q(10,13,[T('آزمایشی طرح کنید که جریان همرفتی در آب را نشان دهد . ( مسیر آن را روی شکل نشان دهید . )'),F('pdf:workbook.pdf#41,37,290.76,162.1,459.77')],[T('تا سه چهارم ظرف شیشه ای را آب می ریزیم و یک سمت ظرف را مطابق شکل روی شعله قرار می دهیم و با قطره چکان ، چند قطره جوهر در سمت دیگر آب می چکانیم و مسیر حرکت جوهر ( جریان همرفتی ) را مشاهده می کنیم .'),F('pdf:answers10.pdf#2,37.35,464.6,197.05,629.61')])
Q(10,14,[T('آب سماور و کتری ، بیش تر از کدام طریق گرم شده و به جوش می آید ؟ توضیح دهید .'),F('pdf:workbook.pdf#41,44.25,480.02,152.25,630.77')],'همرفت – آب از پایین گرم شده و به سمت بالا حرکت می کند . با حرکت آب داغ از ته ظرف به طرف سمت بالا ، آب سرد بالای ظرف به سمت پایین حرکت می کند تا جای آب گرم را بگیرد . با تکرار این فرایند ( جریان همرفتی ) همه آب گرم می شود .')
Q(10,15,[T('بخاری یا رادیاتور در گوشه اتاقتان ، بیش تر از کدام طریق هوای اتاق را گرم می کند ؟ توضیح دهید .'),F('pdf:workbook.pdf#41,37,671.05,195.5,785.65')],'همرفت – بخاری یا رادیاتور داغ است و هوای اطراف خود را گرم می کند . هوای گرم که سبک است به بالا حرکت می کند و هوای سرد و سنگین از پایین حرکت می کند تا جای هوای گرم را بگیرد . هوای سرد هم گرم شده و به بالا حرکت می کند و این کار ادامه دارد . بر اثر این جریان همرفتی هوای کلاس یا اتاق گرم می شود .')
Q(10,16,[T('مینا در هنگام روز ، کنار ساحل ، نسیم دریا را به سمت خودش حس کرد . او مشاهده کرد که دود آتش به طرف خشکی می آید .\nولی وقتی شب شد ، دود از سمت خشکی به سمت ساحل می رفت . او علت این پدیده را برای خانواده اش به صورت زیر توضیح داد .\nشما جاهای خالی را با کلمات ( گرم – سرد ) کامل کنید .'),F('pdf:workbook.pdf#42,235.5,112.48,399.75,203.98'),F('pdf:workbook.pdf#42,37.5,95.23,211.55,199.48'),C('« در روز ، ساحل زودتر از دریا {{0}} می شود . بنابراین هوای نزدیک ساحل {{1}} شده و به بالا می رود و هوای روی دریا که {{2}} است ، حرکت می کند تا جای آن را بگیرد و ما آن را به صورت نسیمی حس می کنیم و دود به سمت ساحل کشیده می شود .\nولی در هنگام شب ، ساحل زودتر {{3}} می شود و آب دریا که در طول روز {{4}} شده است هوای نزدیک خود را {{5}} می کند . هوای {{6}} روی دریا به سمت بالا می رود و هوای {{7}} ساحل حرکت می کند تا جای آن را بگیرد در نتیجه دود را به سمت دریا می برد . »')],'به ترتیب : گرم – گرم – سرد – سرد – گرم – گرم – گرم – سرد')
Q(10,17,'کدام یک از مواد زیر ، بیش تر تابش گرمایی خورشید را جذب می کند و گرم تر می شود ؟ دلیل انتخاب خود را بنویسید .\nالف- آب  ب- آینه  ج- آسفالت\nدلیل : ........................','آسفالت زیرا تیره و ناهموار است .')
Q(10,18,[T('شکل زیر ، جذب تابش گرمایی به وسیله صفحه های فلزی را نشان می دهد . آن را تفسیر کنید .'),F('pdf:workbook.pdf#42,29,421.8,210,576|-42,29,420,210,432')],'بخاری برقی استوانه ای بین دو ورقه فلزی ، یکی صیقلی و براق و دیگری سیاه و مات ، قرار دارد و در طرف دیگر ورقه ها ، چوب پنبه با پارافین یا موم چسبانده شده است . وقتی بخاری روشن می شود ، می بینیم که چوب پنبه پشت ورقه فلزی سطح سیاه زودتر می افتد . نتیجه می گیریم که اجسام تیره و ناهموار ، انرژی تابشی بیشتری جذب می کند و سطوح صاف و براق مقدار کمتری از انرژی تابشی را جذب و بیشتر آن را بازتابش می کنند .')
Q(10,19,[T('الف- آزمایشی طرح کنید که نشان دهد میزان تابش گرمایی یک جسم به رنگ جسم بستگی دارد .'),C('{{0}}\n{{1}}'),T('ب- نمودار دما – زمان این آزمایش به صورت زیر است :'),F('pdf:workbook.pdf#42,63,682,225,794'),C('نمودار شماره {{2}} مربوط به جسم سیاه و نمودار شماره {{3}} مربوط به جسم سفید است .')],'الف- در دو قوطی فلزی که سطح بیرونی یکی سفید و دیگری تیره است ، مقدار مساوی آب داغ با دمای یکسان می ریزیم و در هر کدام یک دماسنج قرار می دهیم و دمای آن ها را هر ۵ دقیقه یادداشت می کنیم . می بینیم که آب درون قوطی تیره رنگ سریع تر سرد می شود ( مایع دماسنج سریعتر پایین می آید ) زیرا تابش گرمایی بیشتری دارد .\nب- نمودار شماره ۱ مربوط به جسم سیاه است و نمودار شماره ۲ مربوط به جسم سفید است .')
Q(10,20,[C('میزان تابش گرمایی یک جسم به چه عواملی بستگی دارد ؟ توضیح دهید .\n{{0}}\n{{1}}')],'به دمای جسم و رنگ جسم – هرچه دمای جسم بیشتر باشد و رنگ جسم تیره تر باشد ، مقدار بیشتری انرژی تابشی منتشر می کند .')
Q(10,21,[T('با توجه به نمودار مقابل ، به سؤالات زیر پاسخ دهید :'),F('pdf:workbook.pdf#43,32,130,277,260'),C('الف- نمودار را تفسیر کنید . {{0}}\nب- چرا بهتر است بخاری ها به رنگ تیره ولی آبگرم کن ها به رنگ سفید باشند ؟\nبخاری ها : {{1}}\nآبگرم کن ها : {{2}}'),T('ج- سینا می گوید ؛ یک لیوان چای کم رنگ سریع تر سرد می شود ولی مهران می گوید ؛ یک لیوان چای پر رنگ سریع تر سرد می شود .\nشما با نظر کدام یک موافق هستید ؟ دلیل خود را بنویسید .'),F('pdf:workbook.pdf#43,49.6,397.02,219.35,473.71'),C('{{3}}\nد- سفید بودن خرس قطبی چه کمکی به آن می کند ؟'),F('pdf:workbook.pdf#43,36.75,520.48,145.5,602.23'),C('{{4}}')],'الف- نمودار نشان می دهد که هر چه جسم تیره تر باشد ، میزان تابش گرمایی آن بیشتر است .\nب- زیرا بخاری به رنگ تیره ، تابش گرمایی بیش تری دارد و محیط را بیش تر گرم می کند – زیرا رنگ سفید تابش گرمایی کم تری دارد در نتیجه ، گرمای آب آبگرم کن کمتر هدر می رود .\nج- مهران ، زیرا چای پر رنگ ، تیره تر است و رنگ تیره تابش گرمایی بیش تری دارد بنابراین گرما را سریع تر از دست می دهد و زودتر سرد می شود .\nد- رنگ سفید تابش گرمایی خیلی کمی دارد بنابراین گرمای بدن خرس سفید خیلی کم به محیط منتشر می شود و در نتیجه گرمای بدنش هدر نمی رود .')
Q(10,22,[T('چرا رادیاتور خودرو را از جنس فلز ، تیره و با سطح بزرگی می سازند ؟'),F('pdf:workbook.pdf#43,36.75,620.27,159.7,729.52')],'گرمای موتور به رادیاتور منتقل می شود . این طراحی رادیاتور ، سبب انتقال خیلی خوب گرما از موتور خودرو به هوای بیرون به هر سه روش رسانش ، همرفت و تابش خواهد شد .')
Q(10,23,'راه های جلوگیری از اتلاف گرما در خانه را در فصل زمستان بنویسید .','گرفتن شکاف و درز های در و پنجره ها – استفاده از پنجره های دو جداره – استفاده از فرش و موکت – سقف عایق')
Q(10,24,[T('وقتی به مسافرت می روید ، فلاسک ( دما بان ) چای شما چگونه دما را برای مدت نسبتا طولانی ثابت نگه می دارد ؟'),F('pdf:workbook.pdf#44,47.5,58.7,117.38,185.8')],'اصلی ترین جزء فلاسک یک بطری شیشه ای دو جداره است که بین آن خلأ است و این خلأ نارسانا بوده و از انتقال گرما به بیرون جلوگیری می کند . روی سطح بطری شیشه ای هم از درون و هم از بیرون نقره اندود است که گرما را به داخل بازتاب می کند و به بیرون هم تابش نمی کند .\nدر پوش آن هم عایق است تا گرما را به بیرون منتقل نکند .')
Q(10,25,'تفاوت انتقال گرما از طریق تابش با انتقال گرما از طریق همرفت و رسانش چیست ؟','در انتقال گرما به روش تابش ، نیازی به محیط مادی نیست و از خلأ ( فضای بدون هوا ) هم عبور می کند ولی در رسانش و همرفت به محیط مادی نیاز است .')
