FIGURES={
 'g7_ch07_mcq06':['pdf:workbook.pdf#29,34.45,649.51,324.7,787.51'],
 'g7_ch08_mcq05':['pdf:workbook.pdf#34,31.45,350.5,257.65,426.65'],
 'g7_ch08_mcq06':['pdf:workbook.pdf#34,37.7,506.25,239.61,596.1'],
 'g7_ch08_mcq07':['pdf:workbook.pdf#34,34,647,307,794'],
 'g7_ch09_mcq03':['pdf:workbook.pdf#38,30.75,668.97,317.18,794.07'],
 'g7_ch10_mcq02':['pdf:workbook.pdf#44,47.5,414.39,317.9,593.92'],
 'g7_ch10_mcq03':['pdf:workbook.pdf#44,47.5,611.54,200.55,705.82']}

def write():
    manifest=[]
    source={r['id']:r for r in json.loads((ROOT/'qa/source/all-chapters-index.json').read_text())}
    from native_scientific_figures import OriginalFigures
    originals=OriginalFigures()
    for ch in range(6,11):
        path=ASSETS/f'content/chapter{ch}.json'
        questions=json.loads(path.read_text())
        for q in questions:
            cid=q['canonicalId'];record=json.loads(json.dumps(DATA[cid]))
            if q['section']=='چهارگزینه‌ای':
                stem,options,key=MCQ[ch][q['sourceNumber']-1]
                step=q['steps'][0]
                assert source[cid]['keyLetter']==key,cid
                step['options']=[dict(text=letter+'- '+value,correct=letter==key)for letter,value in zip(['الف','ب','ج','د'],options)]
            blocks=record['question']
            for asset in FIGURES.get(cid,[]):
                if not any(b.get('asset')==asset for b in blocks):blocks.insert(1,F(asset))
            originals.apply(cid,blocks)
            q['nativeQuestion']=blocks;q['nativeAnswer']=record['answer']
            q['nativeEdition']='1405-visual-transcription-v2'
            payload=json.dumps(record,ensure_ascii=False,sort_keys=True).encode()
            manifest.append(dict(id=cid,questionId=q['id'],sourceQuestion=q['sourceQuestionVisual'],sourceAnswer=q['answerVisual'],nativeSha256=hashlib.sha256(payload).hexdigest()))
        path.write_text(json.dumps(questions,ensure_ascii=False,indent=2)+'\n')
    assert len(manifest)==128 and len(DATA)==128
    originals.finish()
    (ROOT/'qa/source/native-chapters-six-to-ten-manifest.json').write_text(json.dumps(dict(edition=1405,questions=manifest),ensure_ascii=False,indent=2)+'\n')

for ch,entries in MCQ.items():
    for number,(stem,options,key) in enumerate(entries,1):Q(ch,number,[T(stem),I()],key,mcq=True)

if __name__=='__main__':write()
